import type { ReactNode } from 'react';
import { motion, useReducedMotion, type Variants } from 'framer-motion';
import { Link } from 'react-router';
import { useHoverCapable } from '@/hooks/useHoverCapable';
import { BENTO_DUR_ENTRY_S, BENTO_EASE_ENTRY, BENTO_LIFT_HOVER } from './motion';
import { useCardGlow } from './useCardGlow';
import styles from './BentoCard.module.css';

const MotionLink = motion.create(Link);

export type BentoSpan = 'sm' | 'md' | 'lg' | 'tall' | 'wide' | 'full';
export type BentoTone = 'default' | 'cyan' | 'green';

interface BentoCardProps {
  /** Grid footprint. Maps to a span class; collapses responsively. */
  span?: BentoSpan;
  /** Which neon glow tints the cursor-follow border illumination. */
  tone?: BentoTone;
  /** When set, the whole card is a router Link to this route. */
  to?: string;
  /** Fallback accessible name for the link branch — ignored when `labelledBy`
   *  is set. Prefer `labelledBy`: an aria-label replaces the link's computed
   *  name, hiding the tile's heading and stats from assistive tech. */
  label?: string;
  /** id of the tile's heading; names the link via aria-labelledby. */
  labelledBy?: string;
  /** Extra class merged onto the card root. */
  className?: string;
  children: ReactNode;
}

const spanClass: Record<BentoSpan, string> = {
  sm: styles.spanSm,
  md: styles.spanMd,
  lg: styles.spanLg,
  tall: styles.spanTall,
  wide: styles.spanWide,
  full: styles.spanFull,
};

const toneClass: Record<BentoTone, string> = {
  default: styles.toneDefault,
  cyan: styles.toneCyan,
  green: styles.toneGreen,
};

/**
 * A single bento tile. Inherits the parent grid's `hidden`→`show` variant so it
 * settles in on the staggered kinetic entry, lifts subtly on hover, and renders
 * a cursor-following perimeter glow. All transform/opacity-only so it composites
 * on the GPU; `useReducedMotion` turns entry and hover into no-ops so the tile
 * renders settled on first paint (belt-and-braces with the global
 * prefers-reduced-motion reset), and hover effects only attach when the pointer
 * can actually hover so taps never strand them.
 */
export function BentoCard({
  span = 'md',
  tone = 'default',
  to,
  label,
  labelledBy,
  className: extraClassName,
  children,
}: BentoCardProps) {
  const reduce = useReducedMotion();
  const hoverCapable = useHoverCapable();
  const glow = useCardGlow<HTMLDivElement & HTMLAnchorElement>();

  const itemVariants: Variants = reduce
    ? { hidden: {}, show: {} }
    : {
        hidden: { opacity: 0, scale: 0.94, y: 24 },
        show: {
          opacity: 1,
          scale: 1,
          y: 0,
          transition: { duration: BENTO_DUR_ENTRY_S, ease: BENTO_EASE_ENTRY },
        },
      };

  const hover = reduce || !hoverCapable ? undefined : { scale: BENTO_LIFT_HOVER };

  const className = [styles.card, spanClass[span], toneClass[tone], extraClassName]
    .filter(Boolean)
    .join(' ');

  const inner = <span className={styles.glow} aria-hidden="true" />;

  if (to) {
    return (
      <MotionLink
        ref={glow.ref}
        to={to}
        aria-labelledby={labelledBy}
        aria-label={labelledBy ? undefined : label}
        className={`${className} ${styles.link}`}
        variants={itemVariants}
        whileHover={hover}
        whileTap={reduce ? undefined : { scale: 0.995 }}
        onPointerMove={glow.onPointerMove}
        onPointerLeave={glow.onPointerLeave}
      >
        {inner}
        <span className={styles.body}>{children}</span>
      </MotionLink>
    );
  }

  return (
    <motion.div
      ref={glow.ref}
      className={className}
      variants={itemVariants}
      whileHover={hover}
      onPointerMove={glow.onPointerMove}
      onPointerLeave={glow.onPointerLeave}
    >
      {inner}
      <div className={styles.body}>{children}</div>
    </motion.div>
  );
}

import { useEffect, useId, useMemo, useRef, useState } from 'react';
import { useReducedMotion } from 'framer-motion';
import { useTranslation } from 'react-i18next';
import { BentoCard } from '@/components/bento/BentoCard';
import { useFetchJson } from '@/hooks/useFetchJson';
import { CORPUS, type GacarIndex } from '@/lib/content';
import { withAlpha } from '@/lib/color';
import { CardCta } from './CardCta';
import shared from './widgets.module.css';
import styles from './RadarWidget.module.css';

/** One plotted GACAR Part: polar position + visual weight + label. */
interface Blip {
  angle: number;
  radiusFrac: number;
  size: number;
  bright: number;
  title: string;
}

/**
 * Map the real GACAR corpus onto the radar scope: each Part is a contact placed
 * in its domain's angular sector and pushed outward by page-count (corpus depth),
 * so the scope reads as genuine regulatory coverage. Deterministic — no real-time
 * feed — but data-driven rather than decorative.
 */
export function buildBlips(data: GacarIndex | null | undefined): Blip[] {
  if (!data || data.documents.length === 0) return [];
  const cats = data.categories.map((c) => c.id);
  const nCat = cats.length || 1;
  const pages = data.documents.map((d) => d.pages);
  const minP = Math.min(...pages);
  const span = Math.max(1, Math.max(...pages) - minP);
  const sectorWidth = ((Math.PI * 2) / nCat) * 0.82;
  const perSector: Record<string, number> = {};

  return data.documents.map((d) => {
    const sector = Math.max(0, cats.indexOf(d.category));
    const idx = (perSector[d.category] = (perSector[d.category] ?? 0) + 1);
    // Sector centred at the top (−90°), Parts fanned within it by a golden offset.
    const base = (sector / nCat) * Math.PI * 2 - Math.PI / 2;
    const frac = ((idx * 0.61803) % 1) - 0.5;
    const depth = (d.pages - minP) / span; // 0..1
    return {
      angle: base + frac * sectorWidth,
      radiusFrac: 0.4 + depth * 0.52, // deeper Parts sit further out
      size: 1.8 + depth * 2.6,
      bright: 0.45 + depth * 0.5,
      title: `${d.part} · ${d.title}`,
    };
  });
}

/** Read a CSS custom property off :root so canvas paint stays token-driven. */
function cssVar(name: string, fallback: string): string {
  const v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return v || fallback;
}

/**
 * The dashboard's "regulatory coverage map" — a radar scope whose contacts are the
 * 74 GACAR Parts, grouped by domain sector and weighted by corpus depth. Anti-aliased
 * via devicePixel scaling; a continuous sweep lights contacts as it passes, and a
 * single roving tooltip names the Part under the pointer. Honours reduced-motion by
 * painting a single static frame (data still shown).
 */
export function RadarWidget() {
  const { t } = useTranslation();
  const reduce = useReducedMotion();
  const headingId = useId();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const { data, loading } = useFetchJson<GacarIndex>(CORPUS.regulations.index);
  const blips = useMemo(() => buildBlips(data), [data]);
  const [tip, setTip] = useState<{ title: string; left: number; top: number } | null>(null);
  const lastTitle = useRef<string | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const cyan = cssVar('--neon-cyan', '#3fe0ff');
    const ring = cssVar('--border-bright', '#26384a');
    const green = cssVar('--neon-green', '#2bffb0');

    let dpr = Math.max(1, window.devicePixelRatio || 1);
    let cssW = 0;
    let cssH = 0;

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      cssW = rect.width;
      cssH = rect.height;
      dpr = Math.max(1, window.devicePixelRatio || 1);
      canvas.width = Math.round(cssW * dpr);
      canvas.height = Math.round(cssH * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const draw = (sweep: number) => {
      const cx = cssW / 2;
      const cy = cssH / 2;
      const maxR = Math.min(cssW, cssH) / 2 - 6;
      if (maxR <= 0) return;

      ctx.clearRect(0, 0, cssW, cssH);

      // Range rings + cross-hairs
      ctx.strokeStyle = ring;
      ctx.lineWidth = 1;
      for (let i = 1; i <= 3; i += 1) {
        ctx.globalAlpha = 0.5;
        ctx.beginPath();
        ctx.arc(cx, cy, (maxR * i) / 3, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.globalAlpha = 0.35;
      ctx.beginPath();
      ctx.moveTo(cx - maxR, cy);
      ctx.lineTo(cx + maxR, cy);
      ctx.moveTo(cx, cy - maxR);
      ctx.lineTo(cx, cy + maxR);
      ctx.stroke();

      // Bearing ticks around the perimeter (every 30°, longer on the cardinals)
      ctx.globalAlpha = 0.6;
      for (let a = 0; a < 360; a += 30) {
        const rad = (a * Math.PI) / 180;
        const inner = a % 90 === 0 ? maxR - 10 : maxR - 5;
        ctx.beginPath();
        ctx.moveTo(cx + Math.cos(rad) * inner, cy + Math.sin(rad) * inner);
        ctx.lineTo(cx + Math.cos(rad) * maxR, cy + Math.sin(rad) * maxR);
        ctx.stroke();
      }
      ctx.globalAlpha = 1;

      // Sweep wedge with a fading trailing gradient. The transparent stops are
      // derived from the same token as the leading edge so themed sweeps
      // (cockpit amber, day teal) fade through their own hue, not cyan.
      const trail = 1.1; // radians of trail behind the leading edge
      const grad = ctx.createConicGradient(sweep - trail, cx, cy);
      grad.addColorStop(0, withAlpha(cyan, 0));
      grad.addColorStop(trail / (Math.PI * 2), cyan);
      grad.addColorStop(trail / (Math.PI * 2) + 0.001, withAlpha(cyan, 0));
      ctx.save();
      ctx.globalAlpha = 0.28;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.arc(cx, cy, maxR, sweep - trail, sweep);
      ctx.closePath();
      ctx.fillStyle = grad;
      ctx.fill();
      ctx.restore();

      // Leading edge line
      ctx.strokeStyle = cyan;
      ctx.globalAlpha = 0.8;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx + Math.cos(sweep) * maxR, cy + Math.sin(sweep) * maxR);
      ctx.stroke();
      ctx.globalAlpha = 1;

      // Contacts — one per GACAR Part (cyan = data), brightening to green as the
      // sweep passes, then fading.
      for (const b of blips) {
        const bx = cx + Math.cos(b.angle) * b.radiusFrac * maxR;
        const by = cy + Math.sin(b.angle) * b.radiusFrac * maxR;
        let delta = sweep - b.angle;
        delta = ((delta % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
        const lit = Math.max(0, 1 - delta / 1.4);
        ctx.beginPath();
        ctx.fillStyle = lit > 0.05 ? green : cyan;
        ctx.globalAlpha = Math.min(1, b.bright * (0.6 + lit * 0.7));
        ctx.arc(bx, by, b.size + lit * 1.6, 0, Math.PI * 2);
        ctx.fill();
        if (lit > 0.05) {
          ctx.globalAlpha = lit * 0.4;
          ctx.strokeStyle = green;
          ctx.beginPath();
          ctx.arc(bx, by, b.size + 5, 0, Math.PI * 2);
          ctx.stroke();
        }
      }

      // Centre hub
      ctx.globalAlpha = 1;
      ctx.fillStyle = cyan;
      ctx.beginPath();
      ctx.arc(cx, cy, 2.5, 0, Math.PI * 2);
      ctx.fill();
    };

    // Roving tooltip: hit-test the nearest Part contact under the pointer. Uses
    // raw canvas (physical) coordinates — the raster isn't direction-mirrored, so
    // percentage left/top track the painted blip in both LTR and RTL.
    const onMove = (e: MouseEvent) => {
      const cx = cssW / 2;
      const cy = cssH / 2;
      const maxR = Math.min(cssW, cssH) / 2 - 6;
      if (maxR <= 0 || blips.length === 0) return;
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;
      let best: Blip | null = null;
      let bestD = Infinity;
      let bx = 0;
      let by = 0;
      for (const b of blips) {
        const px = cx + Math.cos(b.angle) * b.radiusFrac * maxR;
        const py = cy + Math.sin(b.angle) * b.radiusFrac * maxR;
        const d = Math.hypot(px - mx, py - my);
        if (d < bestD) {
          bestD = d;
          best = b;
          bx = px;
          by = py;
        }
      }
      if (best && bestD <= Math.max(10, best.size + 6)) {
        if (lastTitle.current !== best.title) {
          lastTitle.current = best.title;
          setTip({ title: best.title, left: (bx / cssW) * 100, top: (by / cssH) * 100 });
        }
      } else if (lastTitle.current !== null) {
        lastTitle.current = null;
        setTip(null);
      }
    };

    const onLeave = () => {
      lastTitle.current = null;
      setTip(null);
    };

    resize();

    const observer = new ResizeObserver(() => {
      resize();
      if (reduce) draw(-Math.PI / 4);
    });
    observer.observe(canvas);
    canvas.addEventListener('mousemove', onMove);
    canvas.addEventListener('mouseleave', onLeave);

    const cleanupListeners = () => {
      observer.disconnect();
      canvas.removeEventListener('mousemove', onMove);
      canvas.removeEventListener('mouseleave', onLeave);
    };

    if (reduce) {
      draw(-Math.PI / 4); // single static frame
      return cleanupListeners;
    }

    let raf = 0;
    let last = performance.now();
    let sweep = 0;
    const speed = 1.1; // radians / second
    const loop = (now: number) => {
      sweep = (sweep + ((now - last) / 1000) * speed) % (Math.PI * 2);
      last = now;
      draw(sweep);
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);

    return () => {
      cancelAnimationFrame(raf);
      cleanupListeners();
    };
  }, [reduce, blips]);

  const parts = data?.count ?? 0;
  const domains = data?.categories.length ?? 0;
  const caption = t('home.dashboard.radar.concept', { parts, domains });

  return (
    <BentoCard span="tall" tone="cyan" to="/library" labelledBy={headingId}>
      <p className={shared.eyebrow}>{t('home.dashboard.radar.eyebrow')}</p>
      {/* The tile's design has no visible title; the sr-only heading names the
          link and keeps the tile in the document outline. The canvas stays
          decorative to AT — the visible caption carries the coverage figure. */}
      <h3 id={headingId} className={shared.srOnly}>
        {t('home.dashboard.radar.title')}
      </h3>
      <div className={styles.scope}>
        <canvas ref={canvasRef} className={styles.canvas} aria-hidden="true" />
        {tip && (
          <span
            className={styles.tooltip}
            style={{ left: `${tip.left}%`, top: `${tip.top}%` }}
            aria-hidden="true"
          >
            {tip.title}
          </span>
        )}
      </div>
      {loading || !data ? (
        <span className={`${shared.skeleton} ${shared.skeletonText}`} />
      ) : (
        <p className={styles.concept}>{caption}</p>
      )}
      <CardCta label={t('home.dashboard.radar.cta')} />
    </BentoCard>
  );
}

import { fin } from '@/calc/guards';
import { fmtInt } from './format';
import styles from './GaugeDial.module.css';

interface GaugeDialProps {
  /** Already-translated label under the dial. */
  label: string;
  value: number | null;
  min: number;
  max: number;
  unit: string;
  /** Decimal places for the centre readout; 0 (default) renders a whole number. */
  decimals?: number;
}

/** Sweep geometry: −120° (min) to +120° (max), needle pointing up at mid. */
const SWEEP_FROM = -120;
const SWEEP_TO = 120;

/** Needle rotation for a value, clamped to the dial's sweep. */
export function gaugeAngle(value: number, min: number, max: number): number {
  if (!fin(value, min, max) || max <= min) return SWEEP_FROM;
  const t = Math.min(1, Math.max(0, (value - min) / (max - min)));
  return SWEEP_FROM + t * (SWEEP_TO - SWEEP_FROM);
}

const tickAngles = Array.from(
  { length: 11 },
  (_, i) => SWEEP_FROM + (i * (SWEEP_TO - SWEEP_FROM)) / 10,
);

/**
 * A small instrument-style dial that sweeps its needle to the computed value
 * (CSS transition; snaps under reduced motion). Purely decorative company for
 * a ResultStat — the readable value stays in the stat, so the dial is hidden
 * from AT.
 */
export function GaugeDial({ label, value, min, max, unit, decimals = 0 }: GaugeDialProps) {
  const angle = value != null ? gaugeAngle(value, min, max) : SWEEP_FROM;
  const readout = value == null ? '—' : decimals > 0 ? value.toFixed(decimals) : fmtInt(value);
  return (
    <div className={styles.gauge} aria-hidden="true">
      <svg viewBox="0 0 120 120" width={120} height={120} className={styles.svg}>
        <circle cx={60} cy={60} r={54} fill="none" stroke="var(--border-bright)" strokeWidth="2" />
        {tickAngles.map((a) => (
          <line
            key={a}
            x1={60}
            y1={14}
            x2={60}
            y2={a % 60 === 0 ? 24 : 20}
            stroke="var(--text-dim)"
            strokeWidth={a % 60 === 0 ? 2 : 1}
            transform={`rotate(${a} 60 60)`}
          />
        ))}
        <g className={styles.needle} style={{ transform: `rotate(${angle.toFixed(2)}deg)` }}>
          <path d="M 60 60 L 57 56 L 60 18 L 63 56 Z" fill="var(--neon-cyan)" />
        </g>
        <circle cx={60} cy={60} r={5} fill="var(--text)" />
        <text x={60} y={92} textAnchor="middle" className={styles.value}>
          {readout}
        </text>
        <text x={60} y={104} textAnchor="middle" className={styles.unit}>
          {unit}
        </text>
      </svg>
      <p className={styles.label}>{label}</p>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import styles from './SelectionPopover.module.css';

export interface SelectionRect {
  top: number;
  left: number;
  width: number;
  height: number;
}

interface Props {
  /** Viewport-relative rect of the current selection (position: fixed). */
  rect: SelectionRect;
  onHighlight: () => void;
  onSaveNote: (note: string) => void;
  onClose: () => void;
}

/**
 * A small floating toolbar shown over a text selection in the document reader,
 * offering "Highlight" or "Add note". Self-contained: it manages the note-entry
 * textarea locally and reports the result to the reader via callbacks.
 */
export function SelectionPopover({ rect, onHighlight, onSaveNote, onClose }: Props) {
  const { t } = useTranslation();
  const [noteMode, setNoteMode] = useState(false);
  const [text, setText] = useState('');
  const ref = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (noteMode) inputRef.current?.focus();
  }, [noteMode]);

  // Dismiss on Escape from anywhere inside the popover.
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      e.preventDefault();
      onClose();
    }
  };

  const style = {
    insetBlockStart: `${rect.top + rect.height + 6}px`,
    insetInlineStart: `${rect.left}px`,
  };

  return (
    <div
      ref={ref}
      className={styles.popover}
      style={style}
      role="dialog"
      aria-label={t('document.annotate')}
      onKeyDown={onKeyDown}
      onMouseDown={(e) => e.preventDefault() /* keep the text selection alive */}
    >
      {noteMode ? (
        <div className={styles.noteBox}>
          <textarea
            ref={inputRef}
            className={styles.noteInput}
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder={t('document.notePlaceholder')}
            rows={3}
          />
          <div className={styles.row}>
            <button type="button" className={styles.ghost} onClick={onClose}>
              {t('common.cancel')}
            </button>
            <button
              type="button"
              className={styles.primary}
              disabled={!text.trim()}
              onClick={() => onSaveNote(text.trim())}
            >
              {t('document.saveNote')}
            </button>
          </div>
        </div>
      ) : (
        <div className={styles.row}>
          <button type="button" className={styles.action} onClick={onHighlight}>
            <span aria-hidden="true">🖊</span> {t('document.highlight')}
          </button>
          <button type="button" className={styles.action} onClick={() => setNoteMode(true)}>
            <span aria-hidden="true">✎</span> {t('document.addNote')}
          </button>
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef, useState, type ReactNode } from 'react';
import { Link } from 'react-router';
import { useTranslation } from 'react-i18next';
import { CaptainAvatar } from '@/components/CaptainAvatar';
import { DockIcon } from '@/app/DockIcons';
import { markOnboardingSeen, closeTour } from '@/lib/prefs/onboardingPrefs';
import { lockBodyScroll, unlockBodyScroll } from '@/lib/scrollLock';
import styles from './OnboardingTour.module.css';

/** A simple globe glyph for the bilingual step — matches the DockIcon line style. */
function GlobeIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
      <circle cx="12" cy="12" r="9" />
      <path d="M3 12h18" />
      <path d="M12 3c2.5 2.5 3.8 5.7 3.8 9s-1.3 6.5-3.8 9c-2.5-2.5-3.8-5.7-3.8-9S9.5 5.5 12 3Z" />
    </svg>
  );
}

interface Step {
  id: string;
  /** Optional route the step links to ("go there"). */
  to?: string;
  icon: ReactNode;
}

/** One step per core surface — each introduces it and (optionally) links there. */
const STEPS: Step[] = [
  { id: 'welcome', icon: <CaptainAvatar size="lg" pose="wave" decorative /> },
  { id: 'library', to: '/library', icon: <DockIcon route="/library" /> },
  { id: 'tools', to: '/tools', icon: <DockIcon route="/tools" /> },
  { id: 'captainAdel', to: '/chat', icon: <DockIcon route="/chat" /> },
  { id: 'bilingual', icon: <GlobeIcon /> },
];

const TITLE_ID = 'onboarding-tour-title';

/**
 * First-run welcome tour: a centered modal carousel introducing the core
 * surfaces. Lazily mounted by Layout only on a first visit to the home route;
 * every dismissal path persists "seen" via markOnboardingSeen(). Overlay
 * mechanics (scroll-lock, focus-restore, Escape, Tab trap) mirror CommandPalette.
 */
export default function OnboardingTour() {
  const { t } = useTranslation();
  const [index, setIndex] = useState(0);
  const boxRef = useRef<HTMLDivElement>(null);

  const step = STEPS[index];
  const isLast = index === STEPS.length - 1;

  // Lock body scroll, move focus into the dialog, and restore it on unmount.
  useEffect(() => {
    const restoreFocusTo = document.activeElement as HTMLElement | null;
    lockBodyScroll();
    const id = window.setTimeout(
      () => boxRef.current?.querySelector<HTMLElement>('[data-autofocus]')?.focus(),
      50,
    );
    return () => {
      unlockBodyScroll();
      window.clearTimeout(id);
      restoreFocusTo?.focus?.();
    };
  }, []);

  function dismiss() {
    markOnboardingSeen();
    closeTour();
  }

  // Escape dismisses from anywhere inside; Tab is trapped within the box so
  // focus can never fall behind the scrim.
  function onKeyDown(e: React.KeyboardEvent) {
    if (e.key === 'Escape') {
      e.preventDefault();
      dismiss();
      return;
    }
    if (e.key !== 'Tab') return;
    const box = boxRef.current;
    if (!box) return;
    const focusable = Array.from(
      box.querySelectorAll<HTMLElement>('a[href], button:not([disabled])'),
    ).filter((el) => el.tabIndex !== -1);
    if (focusable.length === 0) return;
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    const activeEl = document.activeElement;
    if (e.shiftKey && (activeEl === first || !box.contains(activeEl))) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && (activeEl === last || !box.contains(activeEl))) {
      e.preventDefault();
      first.focus();
    }
  }

  return (
    <div
      className={styles.scrim}
      onClick={(e) => {
        if (e.target === e.currentTarget) dismiss();
      }}
    >
      <div
        ref={boxRef}
        className={styles.box}
        role="dialog"
        aria-modal="true"
        aria-labelledby={TITLE_ID}
        onKeyDown={onKeyDown}
      >
        <button type="button" className={styles.skip} onClick={dismiss} data-autofocus>
          {t('onboarding.skip')}
        </button>

        <div className={styles.icon} aria-hidden="true">
          {step.icon}
        </div>
        <h2 id={TITLE_ID} className={styles.title}>
          {t(`onboarding.steps.${step.id}.title`)}
        </h2>
        <p className={styles.body}>{t(`onboarding.steps.${step.id}.body`)}</p>

        {step.to && (
          <Link className={styles.go} to={step.to} onClick={dismiss}>
            {t('onboarding.goThere')}
          </Link>
        )}

        <div className={styles.dots} aria-hidden="true">
          {STEPS.map((s, i) => (
            <span key={s.id} className={`${styles.dot} ${i === index ? styles.dotActive : ''}`} />
          ))}
        </div>

        <div className={styles.nav}>
          <button
            type="button"
            className={styles.back}
            onClick={() => setIndex((i) => Math.max(0, i - 1))}
            disabled={index === 0}
          >
            {t('onboarding.back')}
          </button>
          <span className={styles.count} aria-live="polite">
            {t('onboarding.progress', { current: index + 1, total: STEPS.length })}
          </span>
          {isLast ? (
            <button type="button" className={styles.next} onClick={dismiss}>
              {t('onboarding.done')}
            </button>
          ) : (
            <button
              type="button"
              className={styles.next}
              onClick={() => setIndex((i) => Math.min(STEPS.length - 1, i + 1))}
            >
              {t('onboarding.next')}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

