import { useEffect, useMemo, useRef, useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router';
import { useTranslation } from 'react-i18next';
import { RequireSession } from './RequireSession';
import { ResultStat } from '@/components/calc/ResultStat';
import { OutputGrid } from '@/components/calc/Grids';
import { FlightForm } from '@/components/account/FlightForm';
import { BLANK_FLIGHT } from '@/components/account/flight';
import {
  addFlight,
  updateFlight,
  deleteFlight,
  exportAll,
  useAccount,
} from '@/lib/services/account';
import { uiIsPro } from '@/lib/services/entitlements';
import {
  summarizeLogbook,
  flightsToCsv,
  csvToFlights,
  filterFlights,
  sortFlights,
  type SortDir,
} from '@/calc/pilot/logbook';
import { LogbookTable } from './LogbookTable';
import { LogbookBreakdown } from './LogbookBreakdown';
import { CountUp } from '@/components/CountUp';
import type { Flight } from '@/lib/services/account';
import { useNoindexMeta } from '@/hooks/usePageMeta';
import { Alert } from '@/components/Alert';
import styles from './account.module.css';
import { triggerDownload } from '@/lib/download';

export function Logbook() {
  const { t } = useTranslation();
  // Session-gated — keep out of the index.
  useNoindexMeta(t('meta.logbook'));
  return (
    <RequireSession>
      <Inner />
    </RequireSession>
  );
}

function Inner() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { flights, entitlement, syncError } = useAccount();
  const isPro = uiIsPro(entitlement);
  const [adding, setAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [params, setParams] = useSearchParams();

  // ── Filter + sort state (pure client-side; nothing persisted) ──
  const [q, setQ] = useState('');
  const [typeFilter, setTypeFilter] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [sort, setSort] = useState<{ key: keyof Flight; dir: SortDir }>({
    key: 'date',
    dir: 'desc',
  });
  const [importNote, setImportNote] = useState('');
  const fileRef = useRef<HTMLInputElement>(null);

  // Deep link from the dashboard "Log a flight" quick action opens the add form.
  useEffect(() => {
    if (params.get('add') === '1') {
      setAdding(true);
      setEditingId(null);
      const next = new URLSearchParams(params);
      next.delete('add');
      setParams(next, { replace: true });
    }
  }, [params, setParams]);

  const types = useMemo(
    () => [...new Set(flights.map((f) => f.type).filter(Boolean))].sort(),
    [flights],
  );
  const view = useMemo(
    () =>
      sortFlights(filterFlights(flights, { q, type: typeFilter, from, to }), sort.key, sort.dir),
    [flights, q, typeFilter, from, to, sort],
  );
  const filtered = view.length !== flights.length;
  const summary = summarizeLogbook(view);
  const editing = editingId ? flights.find((f) => f.id === editingId) : undefined;

  const toggleSort = (key: keyof Flight) =>
    setSort((s) => ({ key, dir: s.key === key && s.dir === 'desc' ? 'asc' : 'desc' }));

  function exportJson() {
    triggerDownload('flygaca-logbook.json', exportAll(), 'application/json');
  }

  function exportCsv() {
    // CSV/PDF export is a Pro feature — send free users to the plans page.
    if (!isPro) {
      navigate('/pricing');
      return;
    }
    triggerDownload('flygaca-logbook.csv', flightsToCsv(flights), 'text/csv');
  }

  async function importCsv(file: File) {
    const text = await file.text();
    const { flights: drafts } = csvToFlights(text);
    drafts.forEach((d) => addFlight(d));
    setImportNote(
      drafts.length ? t('account.imported', { n: drafts.length }) : t('account.importEmpty'),
    );
    window.setTimeout(() => setImportNote(''), 4000);
  }

  return (
    <section className={`container ${styles.page}`}>
      <header className={styles.head}>
        <h1>{t('account.logbook')}</h1>
      </header>

      {syncError && (
        <Alert tone="warning" role="status" icon="⚠">
          {t('account.syncError')}
        </Alert>
      )}

      {flights.length > 0 && (
        <OutputGrid>
          <ResultStat
            label={t('account.totalHours')}
            value={<CountUp to={summary.totalHours} decimals={1} />}
            tone="headline"
          />
          <ResultStat
            label={t('account.pic')}
            value={<CountUp to={summary.picHours} decimals={1} />}
          />
          <ResultStat
            label={t('account.night')}
            value={<CountUp to={summary.nightHours} decimals={1} />}
          />
          <ResultStat
            label={t('account.ifr')}
            value={<CountUp to={summary.ifrHours} decimals={1} />}
          />
          <ResultStat label={t('account.ldg')} value={<CountUp to={summary.landings} />} />
          <ResultStat
            label={t('account.last90')}
            value={<CountUp to={summary.last90.hours} decimals={1} />}
            sub={t('account.flightsLogged', { n: summary.last90.flightCount })}
          />
        </OutputGrid>
      )}

      <div className={styles.actions}>
        <button
          type="button"
          className={`${styles.btn} ${styles.btnPrimary}`}
          onClick={() => {
            setEditingId(null);
            setAdding((a) => !a);
          }}
        >
          {t('account.addFlight')}
        </button>
        <button type="button" className={styles.btn} onClick={() => fileRef.current?.click()}>
          {t('account.importCsv')}
        </button>
        <input
          ref={fileRef}
          type="file"
          accept=".csv,text/csv"
          hidden
          onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) void importCsv(file);
            e.target.value = '';
          }}
        />
        {flights.length > 0 && (
          <>
            <button type="button" className={styles.btn} onClick={exportJson}>
              {t('account.exportData')}
            </button>
            <button type="button" className={styles.btn} onClick={exportCsv}>
              {t('account.exportCsv')}
              {!isPro && <span className={styles.proTag}>{t('upsell.proOnly')}</span>}
            </button>
          </>
        )}
      </div>
      {importNote && (
        <p className={styles.note} role="status">
          {importNote}
        </p>
      )}
      {flights.length > 0 && !isPro && <p className={styles.note}>{t('account.csvProNote')}</p>}

      {adding && (
        <FlightForm
          initial={BLANK_FLIGHT}
          submitLabel={t('account.save')}
          onSubmit={(draft) => {
            addFlight(draft);
            setAdding(false);
          }}
          onCancel={() => setAdding(false)}
        />
      )}

      {editing && (
        <FlightForm
          key={editing.id}
          initial={editing}
          submitLabel={t('account.update')}
          onSubmit={(draft) => {
            updateFlight(editing.id, draft);
            setEditingId(null);
          }}
          onCancel={() => setEditingId(null)}
        />
      )}

      {flights.length === 0 ? (
        <p className={styles.sub}>
          {t('account.emptyLog')}{' '}
          <Link to="/currency" className={styles.inlineLink}>
            {t('currency.title')}
          </Link>
        </p>
      ) : (
        <>
          <div className={styles.filterBar} role="group" aria-label={t('account.filter')}>
            <input
              className={styles.filterInput}
              type="search"
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder={t('account.filterSearch')}
              aria-label={t('account.filterSearch')}
            />
            <select
              className={styles.filterSelect}
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
              aria-label={t('account.type')}
            >
              <option value="">{t('account.allTypes')}</option>
              {types.map((ty) => (
                <option key={ty} value={ty}>
                  {ty}
                </option>
              ))}
            </select>
            <input
              className={styles.filterDate}
              type="date"
              value={from}
              onChange={(e) => setFrom(e.target.value)}
              aria-label={t('account.dateFrom')}
            />
            <input
              className={styles.filterDate}
              type="date"
              value={to}
              onChange={(e) => setTo(e.target.value)}
              aria-label={t('account.dateTo')}
            />
            {filtered && (
              <span className={styles.note} role="status">
                {t('account.showingCount', { shown: view.length, total: flights.length })}
              </span>
            )}
          </div>

          <LogbookTable
            view={view}
            sort={sort}
            onToggleSort={toggleSort}
            onEdit={(id) => {
              setAdding(false);
              setEditingId(id);
            }}
            onDelete={deleteFlight}
          />

          <LogbookBreakdown flights={flights} />
        </>
      )}
    </section>
  );
}

import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { provisionSeats } from '@/lib/services/org';
import { lockBodyScroll, unlockBodyScroll } from '@/lib/scrollLock';
import { Tabs, Tab } from '@/components/ui/Tabs';
import { Button } from '@/components/ui/Button';
import styles from './admin.module.css';

interface ProvisionPanelProps {
  orgId: string;
  seatLimit: number | null;
  seatsUsed: number;
  onClose: () => void;
}

const MODAL_TITLE_ID = 'provision-panel-title';
const CSV_PREVIEW_LIMIT = 5;

export function ProvisionPanel({ orgId, seatLimit, seatsUsed, onClose }: ProvisionPanelProps) {
  const { t } = useTranslation();
  const [emails, setEmails] = useState('');
  const [csvFile, setCsvFile] = useState<File | null>(null);
  const [csvEmails, setCsvEmails] = useState<string[]>([]);
  const [inputMode, setInputMode] = useState<'manual' | 'csv'>('manual');
  const [expiresAt, setExpiresAt] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [csvError, setCsvError] = useState('');
  const [results, setResults] = useState<Array<{
    email: string;
    success: boolean;
    error?: string;
  }> | null>(null);

  useEffect(() => {
    lockBodyScroll();
    return () => unlockBodyScroll();
  }, []);

  const parseCSV = async (file: File): Promise<string[]> => {
    const text = await file.text();
    return text
      .split('\n')
      .map((line) => line.trim())
      .filter(Boolean)
      .map((line) => line.split(',')[0].trim())
      .filter((email) => email);
  };

  const handleCsvUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setCsvError('');
    setCsvFile(file);
    setCsvEmails([]);

    try {
      const emailsFromCsv = await parseCSV(file);
      if (emailsFromCsv.length === 0) {
        setCsvError(t('business.admin.csvEmpty'));
        setCsvFile(null);
        return;
      }
      setCsvEmails(emailsFromCsv);
    } catch {
      setCsvError(t('business.admin.csvParseError'));
      setCsvFile(null);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    let emailList: string[] = [];
    if (inputMode === 'manual') {
      emailList = emails
        .split('\n')
        .map((e) => e.trim())
        .filter(Boolean);
    } else if (csvFile) {
      try {
        emailList = await parseCSV(csvFile);
      } catch {
        setCsvError(t('business.admin.csvParseError'));
        setIsSubmitting(false);
        return;
      }
    }

    if (emailList.length === 0) {
      setIsSubmitting(false);
      return;
    }

    const res = await provisionSeats(orgId, emailList, expiresAt || undefined);
    if (res) {
      setResults(res.results);
    } else {
      setResults(emailList.map((e) => ({ email: e, success: false, error: 'network-error' })));
    }
    setIsSubmitting(false);
  };

  const availableSeats = seatLimit !== null ? seatLimit - seatsUsed : null;
  const canAddMore = availableSeats === null || availableSeats > 0;

  return (
    <div className={styles.modalOverlay} onClick={onClose}>
      <div
        className={styles.modal}
        role="dialog"
        aria-modal="true"
        aria-labelledby={MODAL_TITLE_ID}
        onClick={(e) => e.stopPropagation()}
      >
        <div className={styles.modalHead}>
          <h2 id={MODAL_TITLE_ID}>{t('business.admin.addSeats')}</h2>
          <button type="button" className={styles.closeButton} onClick={onClose} aria-label="Close">
            ✕
          </button>
        </div>

        {results ? (
          <div className={styles.modalBody}>
            <h3>{t('business.admin.provisionResults')}</h3>
            <ul className={styles.resultsList}>
              {results.map((r) => (
                <li key={r.email} className={r.success ? styles.resultSuccess : styles.resultError}>
                  <bdi dir="ltr">{r.email}</bdi>
                  {r.success ? '✓' : `✗ ${r.error}`}
                </li>
              ))}
            </ul>
            <Button type="button" variant="primary" onClick={onClose}>
              {t('business.admin.done')}
            </Button>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className={styles.modalBody}>
            {seatLimit !== null && (
              <div className={styles.seatInfo}>
                {t('business.admin.seatUsage', {
                  used: seatsUsed,
                  limit: seatLimit,
                  available: availableSeats,
                })}
              </div>
            )}

            {!canAddMore && (
              <div className={styles.warning}>{t('business.admin.seatLimitReached')}</div>
            )}

            <Tabs label={t('business.admin.inputModeLabel')} className={styles.inputModeTabs}>
              <Tab
                active={inputMode === 'manual'}
                onClick={() => {
                  setInputMode('manual');
                  setCsvError('');
                  setCsvFile(null);
                  setCsvEmails([]);
                }}
              >
                {t('business.admin.tabManual')}
              </Tab>
              <Tab
                active={inputMode === 'csv'}
                onClick={() => {
                  setInputMode('csv');
                  setEmails('');
                }}
              >
                {t('business.admin.tabCsv')}
              </Tab>
            </Tabs>

            {inputMode === 'manual' ? (
              <div className={styles.formGroup}>
                <label htmlFor="emails">{t('business.admin.emailsLabel')}</label>
                <textarea
                  id="emails"
                  value={emails}
                  onChange={(e) => setEmails(e.target.value)}
                  placeholder={t('business.admin.emailsPlaceholder')}
                  disabled={!canAddMore}
                  rows={5}
                />
              </div>
            ) : (
              <div className={styles.formGroup}>
                <label htmlFor="csvFile">{t('business.admin.csvLabel')}</label>
                <input
                  type="file"
                  id="csvFile"
                  accept=".csv"
                  onChange={handleCsvUpload}
                  disabled={!canAddMore}
                  className={styles.fileInput}
                />
                {csvFile && csvEmails.length > 0 && (
                  <div className={styles.csvPreview}>
                    <p className={styles.fileInfo}>
                      {t('business.admin.csvSelected', { name: csvFile.name })}
                      {' — '}
                      {t('business.admin.csvPreviewCount', { count: csvEmails.length })}
                    </p>
                    <ul className={styles.csvPreviewList}>
                      {csvEmails.slice(0, CSV_PREVIEW_LIMIT).map((email) => (
                        <li key={email}>
                          <bdi dir="ltr">{email}</bdi>
                        </li>
                      ))}
                    </ul>
                    {csvEmails.length > CSV_PREVIEW_LIMIT && (
                      <p className={styles.csvHint}>
                        {t('business.admin.csvPreviewMore', {
                          count: csvEmails.length - CSV_PREVIEW_LIMIT,
                        })}
                      </p>
                    )}
                  </div>
                )}
                {csvError && <p className={styles.csvErrorMsg}>{csvError}</p>}
                <p className={styles.csvHint}>{t('business.admin.csvHint')}</p>
              </div>
            )}

            <div className={styles.formGroup}>
              <label htmlFor="expiresAt">{t('business.admin.expirationLabel')}</label>
              <input
                type="date"
                id="expiresAt"
                value={expiresAt}
                onChange={(e) => setExpiresAt(e.target.value)}
                disabled={!canAddMore}
              />
            </div>

            <div className={styles.modalFooter}>
              <Button type="button" variant="clay" onClick={onClose}>
                {t('business.admin.cancel')}
              </Button>
              <Button
                type="submit"
                variant="primary"
                disabled={
                  isSubmitting ||
                  !canAddMore ||
                  (inputMode === 'manual' ? !emails.trim() : !csvFile)
                }
              >
                {isSubmitting ? t('business.admin.provisioning') : t('business.admin.sendInvites')}
              </Button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
}

