import { useEffect, useMemo, useRef, useState } from 'react';
import { useSearchParams } from 'react-router';
import { useTranslation } from 'react-i18next';
import { useFetchJson } from '@/hooks/useFetchJson';
import type { QuizBank, QuizData, QuizQuestion } from '@/lib/content';
import { useStudyProgress, gradeCard } from '@/lib/studyProgress';
import { dueKeys, masteredCount } from '@/calc/study/srs';
import { glidePathBins } from '@/calc/study/glidePath';
import { usePrefersReducedMotion } from '@/hooks/usePrefersReducedMotion';
import { GlidePathStrip } from '@/components/study/GlidePathStrip';
import { CaptainAvatar } from '@/components/CaptainAvatar';
import { usePageMeta } from '@/hooks/usePageMeta';
import { courseLd } from '@/lib/seo/jsonld';
import { ProgressBar } from '@/components/ProgressBar';
import { Disclaimer } from '@/components/Disclaimer';
import { HubBackLink } from '@/components/HubBackLink';
import styles from './Study.module.css';
import { shuffle } from '@/calc/study/shuffle';

export function Flashcards() {
  const { t, i18n } = useTranslation();
  usePageMeta(
    t('meta.flashcards'),
    t('metaDesc.flashcards'),
    courseLd({
      title: t('meta.flashcards'),
      description: t('metaDesc.flashcards'),
      path: '/study/flashcards',
      lang: i18n.language,
    }),
  );
  const [reload, setReload] = useState(0);
  const { data, error, loading } = useFetchJson<QuizData>('/data/quiz.json', reload);
  const { fcSrs } = useStudyProgress();
  const [bank, setBank] = useState<QuizBank | null>(null);
  const [params, setParams] = useSearchParams();

  // Deep-link straight into one bank's deck via ?bank=<id> (e.g. from a pack or
  // the hub's weak-topics list). Decks stay per-bank so SRS attribution is exact.
  useEffect(() => {
    if (!data || bank) return;
    const id = params.get('bank');
    const found = id ? data.banks.find((b) => b.id === id) : null;
    if (found) setBank(found);
  }, [data, params, bank]);

  const backToBanks = () => {
    setBank(null);
    if ([...params.keys()].length) setParams({}, { replace: true });
  };

  if (loading)
    return <section className={`container-narrow ${styles.page}`}>{t('common.loading')}</section>;
  if (error || !data)
    return (
      <section className={`container-narrow ${styles.page}`}>
        <div className={styles.errorBox} role="alert">
          <p>{t('common.loadError')}</p>
          <button type="button" className={styles.primary} onClick={() => setReload((r) => r + 1)}>
            {t('library.retry')}
          </button>
        </div>
      </section>
    );

  if (!bank) {
    return (
      <section className={`container-narrow ${styles.page}`}>
        <HubBackLink to="/learn?tab=practice" label={t('nav.learn')} />
        <h1>{t('study.flashcards')}</h1>
        <p className={styles.subtitle}>{t('study.pickBank')}</p>
        <ul className={styles.banks}>
          {data.banks.map((b) => {
            const srs = fcSrs[b.id] ?? {};
            const keys = b.questions.map((_, i) => String(i));
            const due = dueKeys(srs, keys, new Date()).length;
            const mastered = masteredCount(srs);
            return (
              <li key={b.id}>
                <button type="button" className={styles.bank} onClick={() => setBank(b)}>
                  <span className={styles.bankTitle}>{b.title}</span>
                  <span className={styles.bankMeta}>
                    {t('study.questions', { n: b.questions.length })}
                    {due > 0 ? ` · ${t('study.dueCount', { n: due })}` : ''}
                    {mastered > 0 ? ` · ${t('study.masteredCount', { n: mastered })}` : ''}
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
        <Disclaimer compact />
      </section>
    );
  }

  return <Deck bank={bank} onBack={backToBanks} />;
}

type Card = QuizQuestion & { key: string };

function Deck({ bank, onBack }: { bank: QuizBank; onBack: () => void }) {
  const { t } = useTranslation();
  const { fcSrs } = useStudyProgress();
  const reduce = usePrefersReducedMotion();

  const allCards: Card[] = useMemo(
    () => bank.questions.map((c, idx) => ({ ...c, key: String(idx) })),
    [bank],
  );

  // Build the session from the cards due now (fall back to the whole deck).
  const initial = useMemo(() => {
    const srs = fcSrs[bank.id] ?? {};
    const keys = dueKeys(
      srs,
      allCards.map((c) => c.key),
      new Date(),
    );
    const due = allCards.filter((c) => keys.includes(c.key));
    return shuffle(due.length ? due : allCards);
    // Snapshot once on mount — grading mutates the store but shouldn't reshuffle mid-session.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [bank]);

  // One runner serves the initial due-based session and every follow-up
  // (reset / review-missed) session — restart() swaps the queue in place.
  const [queue, setQueue] = useState<Card[]>(initial);
  const [i, setI] = useState(0);
  const [flipped, setFlipped] = useState(false);
  const [got, setGot] = useState(0);
  const [again, setAgain] = useState<Card[]>([]);
  // The graded card's fly-out stage; advance() runs when its animation lands.
  const [leaving, setLeaving] = useState<'known' | 'again' | null>(null);
  const card = queue[i];
  const done = i >= queue.length;

  // Persist the grade immediately — the fly-out is purely cosmetic, so under
  // reduced motion the same step just runs without the leaving stage.
  function grade(correct: boolean) {
    if (leaving) return;
    gradeCard(bank.id, card.key, correct);
    if (correct) setGot((n) => n + 1);
    else setAgain((r) => [...r, card]);
    if (reduce) advance();
    else setLeaving(correct ? 'known' : 'again');
  }

  function advance() {
    setLeaving(null);
    setFlipped(false);
    setI((n) => n + 1);
  }

  // Keyboard: Space/Enter flips; once flipped ←/→ grade again/got-it.
  useEffect(() => {
    if (done) return;
    const onKey = (e: KeyboardEvent) => {
      if (leaving) return;
      if (e.key === ' ' || e.key === 'Enter') {
        e.preventDefault();
        setFlipped((f) => !f);
      } else if (flipped && (e.key === 'ArrowRight' || e.key === '1')) {
        e.preventDefault();
        grade(true);
      } else if (flipped && (e.key === 'ArrowLeft' || e.key === '2')) {
        e.preventDefault();
        grade(false);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [flipped, done, i, leaving]);

  function restart(cards: Card[]) {
    setQueue(shuffle(cards));
    setI(0);
    setFlipped(false);
    setGot(0);
    setAgain([]);
    setLeaving(null);
  }

  return (
    <section className={`container-narrow ${styles.page}`}>
      <button type="button" className={styles.back} onClick={onBack}>
        ← {t('study.back')}
      </button>
      {done ? (
        <div className={styles.result} role="status">
          <p>{t('study.deckDone', { known: got, review: again.length })}</p>
          <div className={styles.resultActions}>
            <button type="button" className={styles.primary} onClick={() => restart(allCards)}>
              {t('study.reset')}
            </button>
            {again.length > 0 && (
              <button type="button" className={styles.secondary} onClick={() => restart(again)}>
                {t('study.reviewUnknowns', { n: again.length })}
              </button>
            )}
          </div>
        </div>
      ) : (
        <CardView
          key={card.key}
          card={card}
          flipped={flipped}
          leaving={leaving}
          onFlip={() => {
            if (!leaving) setFlipped((f) => !f);
          }}
          onGrade={grade}
          onLeaveEnd={advance}
          progress={{ done: i + 1, total: queue.length }}
        />
      )}
      <GlidePathStrip
        bins={glidePathBins(
          fcSrs[bank.id] ?? {},
          allCards.map((c) => c.key),
        )}
      />
    </section>
  );
}

function CardView({
  card,
  flipped,
  leaving,
  onFlip,
  onGrade,
  onLeaveEnd,
  progress,
}: {
  card: Card;
  flipped: boolean;
  leaving: 'known' | 'again' | null;
  onFlip: () => void;
  onGrade: (correct: boolean) => void;
  onLeaveEnd: () => void;
  progress: { done: number; total: number };
}) {
  const { t } = useTranslation();
  const wrapRef = useRef<HTMLDivElement>(null);
  // Native listener rather than React's onAnimationEnd: React only registers
  // the unprefixed event when the environment advertises CSS animation
  // support, which jsdom doesn't — the DOM event itself is dependable.
  // Attached only during the fly-out, so the enter animation never advances.
  useEffect(() => {
    if (!leaving) return;
    const el = wrapRef.current;
    if (!el) return;
    const end = () => onLeaveEnd();
    el.addEventListener('animationend', end);
    return () => el.removeEventListener('animationend', end);
  }, [leaving, onLeaveEnd]);
  const wrapperClass = [
    styles.cardWrapper,
    styles.cardEnter,
    leaving === 'known' ? styles.cardLeaveKnown : '',
    leaving === 'again' ? styles.cardLeaveAgain : '',
  ]
    .filter(Boolean)
    .join(' ');
  return (
    <>
      <p className={styles.qProgress} role="status" aria-live="polite">
        {t('study.progress', { done: progress.done, total: progress.total })}
      </p>
      <ProgressBar percent={Math.round(((progress.done - 1) / progress.total) * 100)} />
      <div
        ref={wrapRef}
        className={wrapperClass}
        role="button"
        tabIndex={0}
        aria-pressed={flipped}
        aria-label={t('study.flipHint')}
        onClick={onFlip}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onFlip();
          }
        }}
      >
        <div className={`${styles.cardInner} ${flipped ? styles.flippedCard : ''}`}>
          <div className={styles.cardFront}>
            <span className={styles.cardQ}>{card.q}</span>
            <span className={styles.cardFlipHint}>{t('study.flipHint')}</span>
          </div>
          <div className={styles.cardBack}>
            <div className={styles.cardBackContent}>
              <span className={styles.cardA}>
                <strong>{card.options[card.answer]}</strong>
                <span className={styles.cardExplain}>{card.explain}</span>
              </span>
            </div>
            <CaptainAvatar size="sm" pose="hold" decorative className={styles.cardAvatar} />
          </div>
        </div>
      </div>
      {!flipped ? (
        <button type="button" className={styles.primary} onClick={onFlip}>
          {t('study.flip')}
        </button>
      ) : (
        <div className={styles.markRow}>
          <button
            type="button"
            className={`${styles.mark} ${styles.markReview}`}
            onClick={() => onGrade(false)}
            disabled={leaving != null}
          >
            {t('study.again')}
          </button>
          <button
            type="button"
            className={`${styles.mark} ${styles.markKnown}`}
            onClick={() => onGrade(true)}
            disabled={leaving != null}
          >
            {t('study.gotIt')}
          </button>
        </div>
      )}
    </>
  );
}

import { useState } from 'react';
import { Link, useNavigate } from 'react-router';
import { useTranslation } from 'react-i18next';
import { canCheckout, startPackCheckout } from '@/lib/services/billing';
import { getStoredRef } from '@/lib/services/referral';
import { getStoredPromo } from '@/lib/services/promo';
import { Disclaimer } from '@/components/Disclaimer';
import { packItemCount, packPrice, type Pack } from '@/lib/prepCatalog';
import type { QuizData } from '@/lib/content';
import styles from './Study.module.css';

/** The locked pack storefront: what's inside, price, Buy (web) / IAP note. */
export function PackStorefront({ pack, questionCount }: { pack: Pack; questionCount: number }) {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const packName = t(`study.packCatalog.${pack.id}.name`);
  const packDesc = t(`study.packCatalog.${pack.id}.desc`);
  const pack2 = pack;

  async function buy() {
    setBusy(true);
    setError('');
    try {
      await startPackCheckout(pack2.id, { ref: getStoredRef(), promo: getStoredPromo() });
    } catch (e) {
      const code = e instanceof Error ? e.message : '';
      if (code === 'sign-in-required') {
        navigate('/account');
        return;
      }
      setError(t('study.packCheckoutError'));
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className={`container ${styles.page}`}>
      <p className={styles.back}>
        <Link to="/study/packs">← {t('study.packs')}</Link>
      </p>
      <header className={styles.packHero}>
        <div className={styles.packHeroTop}>
          <h1>{packName}</h1>
          <span className={styles.proTag}>{t('study.packPaid')}</span>
        </div>
        <p className={styles.packHeroDesc}>{packDesc}</p>

        <p className={styles.packInsideLine}>
          {t('study.packItemCount', { n: packItemCount(pack2) })} ·{' '}
          {t('study.questions', { n: questionCount })}
        </p>

        <div className={styles.packBuyRow}>
          <span className={styles.packBuyPrice}>
            <bdi dir="ltr">{t('study.packPriceOnce', { n: packPrice(pack2) })}</bdi>
          </span>
          {canCheckout() ? (
            <button
              type="button"
              className={styles.primary}
              disabled={busy}
              onClick={() => void buy()}
            >
              {busy ? t('pricing.checkoutBusy') : t('study.packBuy')}
            </button>
          ) : (
            // Native shells buy through store IAP, not Moyasar web checkout.
            <button type="button" className={styles.primary} disabled aria-disabled="true">
              {t('pricing.passComingSoon')}
            </button>
          )}
        </div>
        <p className={styles.packIncludedWith}>
          <Link to="/pricing">{t('study.packIncludedWithPro')}</Link>
        </p>
        {error && (
          <p role="alert" className={styles.notifyError}>
            {error}
          </p>
        )}
      </header>
      <Disclaimer compact />
    </section>
  );
}

/** Total questions across a pack's banks — for the locked page's "what's inside". */
export function countQuestions(data: QuizData | null | undefined, bankIds: string[]): number {
  if (!data) return 0;
  return bankIds.reduce(
    (n, id) => n + (data.banks.find((b) => b.id === id)?.questions.length ?? 0),
    0,
  );
}

import { useEffect, useState } from 'react';
import { Link, useSearchParams } from 'react-router';
import { useTranslation } from 'react-i18next';
import { useFetchJson } from '@/hooks/useFetchJson';
import type { QuizBank, QuizData } from '@/lib/content';
import { useStudyProgress, setLastBank } from '@/lib/studyProgress';
import { usePageMeta } from '@/hooks/usePageMeta';
import { courseLd } from '@/lib/seo/jsonld';
import { Disclaimer } from '@/components/Disclaimer';
import { HubBackLink } from '@/components/HubBackLink';
import { buildSession } from './session';
import { Runner, Shell } from './QuizRunner';
import { findPack } from '@/lib/prepCatalog';
import { hasPackAccess } from '@/lib/services/packEntitlements';
import { useAccount } from '@/lib/services/account';
import styles from './Study.module.css';

export function Quiz() {
  const { t, i18n } = useTranslation();
  usePageMeta(
    t('meta.quiz'),
    t('metaDesc.quiz'),
    courseLd({
      title: t('meta.quiz'),
      description: t('metaDesc.quiz'),
      path: '/study/quiz',
      lang: i18n.language,
    }),
  );
  const [reload, setReload] = useState(0);
  const { data, error, loading } = useFetchJson<QuizData>('/data/quiz.json', reload);
  const { quizBest, flagged } = useStudyProgress();
  const { entitlement, ownedPacks } = useAccount();
  const [bank, setBank] = useState<QuizBank | null>(null);
  const [params, setParams] = useSearchParams();

  // A combined pack session is a paid surface — resolve the pack and gate on access
  // so `/study/quiz?pack=medical` can't bypass the storefront paywall. Per-bank
  // (`?bank=`) and flagged-review sessions stay open (free surfaces).
  const packParam = params.get('pack');
  const gatedPack = packParam ? findPack(packParam) : undefined;
  const packLocked = !!gatedPack && !hasPackAccess(gatedPack, entitlement, ownedPacks);

  // Launch a focused session (pack / single bank / flagged review) from the URL.
  useEffect(() => {
    if (!data || bank || packLocked) return;
    const sess = buildSession(
      data,
      { pack: params.get('pack'), bank: params.get('bank'), review: params.get('review') },
      flagged,
      t,
    );
    if (sess) setBank(sess);
    // Build once when data/params resolve; flagged/t are snapshotted intentionally.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [data, params, bank, packLocked]);

  const openBank = (b: QuizBank) => {
    setBank(b);
    setLastBank(b.id);
  };
  const backToBanks = () => {
    setBank(null);
    if ([...params.keys()].length) setParams({}, { replace: true });
  };

  if (loading) return <Shell>{t('common.loading')}</Shell>;
  if (error || !data)
    return (
      <Shell>
        <div className={styles.errorBox} role="alert">
          <p>{t('common.loadError')}</p>
          <button type="button" className={styles.primary} onClick={() => setReload((r) => r + 1)}>
            {t('library.retry')}
          </button>
        </div>
      </Shell>
    );

  if (packLocked && gatedPack) {
    return (
      <Shell>
        <HubBackLink to="/learn?tab=practice" label={t('nav.learn')} />
        <h1>{t(`study.packCatalog.${gatedPack.id}.name`)}</h1>
        <p className={styles.subtitle}>{t('study.packLockedNote')}</p>
        <Link
          to={`/study/packs/${gatedPack.id}`}
          className={styles.primary}
          style={{ textDecoration: 'none' }}
        >
          {t('study.packView')}
        </Link>
        <Disclaimer compact />
      </Shell>
    );
  }

  if (!bank) {
    return (
      <Shell>
        <HubBackLink to="/learn?tab=practice" label={t('nav.learn')} />
        <h1>{t('study.quiz')}</h1>
        <p className={styles.subtitle}>{t('study.pickBank')}</p>
        <ul className={styles.banks}>
          {data.banks.map((b) => {
            const best = quizBest[b.id];
            return (
              <li key={b.id}>
                <button type="button" className={styles.bank} onClick={() => openBank(b)}>
                  <span className={styles.bankTitle}>{b.title}</span>
                  <span className={styles.bankDesc}>{b.desc}</span>
                  <span className={styles.bankMeta}>
                    {t('study.questions', { n: b.questions.length })}
                    {best != null ? ` · ${t('study.best', { pct: best })}` : ''}
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
        <Disclaimer compact />
      </Shell>
    );
  }

  return <Runner bank={bank} onBack={backToBanks} />;
}

import { Link } from 'react-router';
import { useTranslation } from 'react-i18next';
import { useFetchJson } from '@/hooks/useFetchJson';
import type { GroundSchoolData, QuizData } from '@/lib/content';
import { useStudyProgress } from '@/lib/studyProgress';
import { masteredCount, dueCount } from '@/calc/study/srs';
import { glidePathBins, mergeBins } from '@/calc/study/glidePath';
import { GlidePathStrip } from '@/components/study/GlidePathStrip';
import { ResultStat } from '@/components/calc/ResultStat';
import { OutputGrid } from '@/components/calc/Grids';
import { ProgressBar } from '@/components/ProgressBar';
import { CaptainAvatar } from '@/components/CaptainAvatar';
import styles from './Study.module.css';

export const STUDY_MODES = [
  { to: '/study/quiz', key: 'quiz', icon: '◉' },
  { to: '/study/flashcards', key: 'flashcards', icon: '⇄' },
  { to: '/study/groundschool', key: 'groundschool', icon: '◈' },
  { to: '/study/exam', key: 'exam', icon: '◎' },
  { to: '/study/paths', key: 'paths', icon: '▷' },
  { to: '/study/packs', key: 'packs', icon: '⊞' },
  { to: '/study/sheets', key: 'sheets', icon: '▤' },
] as const;

/**
 * The study dashboard: progress stats, weakest/by-topic/exam-history analytics,
 * quick-resume actions and the study-mode cards. Extracted from the former Study
 * hub so the Learn hub can render it under the shared SearchHero (Practice tab).
 */
export function StudyDashboard() {
  const { t } = useTranslation();
  const quiz = useFetchJson<QuizData>('/data/quiz.json');
  const gs = useFetchJson<GroundSchoolData>('/data/groundschool.json');
  const { quizBest, gsDone, fcSrs, streak, examHistory, flagged, lastBank } = useStudyProgress();

  const now = new Date();
  const banks = quiz.data?.banks ?? [];
  const keysFor = (n: number) => Array.from({ length: n }, (_, i) => String(i));
  const attempted = banks.filter((b) => quizBest[b.id] != null).length;
  const bestValues = banks.map((b) => quizBest[b.id]).filter((v): v is number => v != null);
  const avgBest = bestValues.length
    ? Math.round(bestValues.reduce((s, v) => s + v, 0) / bestValues.length)
    : 0;
  const totalCards = banks.reduce((s, b) => s + b.questions.length, 0);
  const knownCards = Object.values(fcSrs).reduce((s, m) => s + masteredCount(m), 0);
  const dueTotal = banks.reduce(
    (s, b) => s + dueCount(fcSrs[b.id] ?? {}, keysFor(b.questions.length), now),
    0,
  );
  const flaggedTotal = Object.values(flagged).reduce((s, a) => s + a.length, 0);

  const lessons = gs.data?.modules.flatMap((m) => m.lessons) ?? [];
  const doneLessons = lessons.filter((l) => gsDone[l.id]).length;

  // Lowest scores first (unattempted sorts first as "start here") — top 3 focus areas.
  const weakest = banks
    .map((b) => ({ b, best: quizBest[b.id] ?? -1 }))
    .sort((a, z) => a.best - z.best)
    .slice(0, 3);
  const resumeBank = banks.find((b) => b.id === lastBank);

  // The highest streak milestone reached, for a small celebratory nudge.
  const milestone = [365, 100, 30, 7].find((m) => streak.count >= m);

  const progressFor = (key: string): string | null => {
    if (key === 'quiz' && banks.length)
      return t('study.banksProgress', { done: attempted, total: banks.length });
    if (key === 'groundschool' && lessons.length)
      return t('study.lessonsProgress', { done: doneLessons, total: lessons.length });
    if (key === 'flashcards' && totalCards)
      return t('study.cardsProgress', { done: knownCards, total: totalCards });
    return null;
  };

  return (
    <>
      <OutputGrid>
        <ResultStat
          label={t('study.streak')}
          value={streak.count}
          sub={t('study.streakUnit')}
          tone={streak.count > 0 ? 'good' : undefined}
        />
        <ResultStat label={t('study.avgBest')} value={`${avgBest}%`} />
        <ResultStat
          label={t('study.dueToday')}
          value={dueTotal}
          tone={dueTotal > 0 ? 'headline' : undefined}
        />
        <ResultStat label={t('study.lessonsDone')} value={`${doneLessons}/${lessons.length}`} />
      </OutputGrid>

      {banks.length > 0 && (
        <GlidePathStrip
          bins={mergeBins(
            banks.map((b) => glidePathBins(fcSrs[b.id] ?? {}, keysFor(b.questions.length))),
          )}
        />
      )}

      {milestone && (
        <div className={styles.milestoneWrap} role="status">
          <CaptainAvatar size="md" pose="smile" decorative />
          <p className={styles.milestone}>{t('study.streakMilestone', { n: milestone })}</p>
        </div>
      )}

      {/* Quick actions: resume the last bank, drill the flagged review deck, clear due cards. */}
      {(resumeBank || flaggedTotal > 0 || dueTotal > 0) && (
        <div className={styles.quickRow}>
          {resumeBank && (
            <Link to={`/study/quiz?bank=${resumeBank.id}`} className={styles.quickChip}>
              {t('study.resume')}: {resumeBank.title}
            </Link>
          )}
          {dueTotal > 0 && (
            <Link to="/study/flashcards" className={styles.quickChip}>
              {t('study.dueToday')} · {dueTotal}
            </Link>
          )}
          {flaggedTotal > 0 && (
            <Link to="/study/quiz?review=flagged" className={styles.quickChip}>
              {t('study.reviewFlagged', { n: flaggedTotal })}
            </Link>
          )}
        </div>
      )}

      {attempted < banks.length && weakest.length > 0 && (
        <section className={styles.analytics}>
          <h2 className={styles.analyticsHead}>{t('study.weakest')}</h2>
          <ul className={styles.weakList}>
            {weakest.map(({ b, best }) => (
              <li key={b.id}>
                <Link to={`/study/quiz?bank=${b.id}`} className={styles.weakChip}>
                  {b.title}
                  <span className={styles.weakPct}>{best < 0 ? '—' : `${best}%`}</span>
                </Link>
              </li>
            ))}
          </ul>
        </section>
      )}

      {bestValues.length > 0 && (
        <section className={styles.analytics}>
          <h2 className={styles.analyticsHead}>{t('study.byTopic')}</h2>
          <ul className={styles.topicList}>
            {banks
              .filter((b) => quizBest[b.id] != null)
              .map((b) => {
                const learned = masteredCount(fcSrs[b.id] ?? {});
                return (
                  <li key={b.id} className={styles.topicRow}>
                    <span className={styles.topicName}>{b.title}</span>
                    <ProgressBar percent={quizBest[b.id]} label={b.title} />
                    <span className={styles.topicMeta}>
                      {quizBest[b.id]}% · {t('study.masteredCount', { n: learned })}
                    </span>
                  </li>
                );
              })}
          </ul>
        </section>
      )}

      {examHistory.length > 0 && (
        <section className={styles.analytics}>
          <h2 className={styles.analyticsHead}>{t('study.examHistory')}</h2>
          <div className={styles.examBars} role="img" aria-label={t('study.examHistory')}>
            {examHistory.map((r, i) => (
              <span
                key={i}
                className={`${styles.examBar} ${r.passed ? styles.examBarPass : styles.examBarFail}`}
                style={{ blockSize: `${Math.max(8, r.pct)}%` }}
                title={`${r.pct}% · ${r.date}`}
              />
            ))}
          </div>
        </section>
      )}

      <ul className={`${styles.modes} stagger-grid`}>
        {STUDY_MODES.map((m) => {
          const prog = progressFor(m.key);
          return (
            <li key={m.key}>
              <Link to={m.to} className={styles.mode}>
                <span className={styles.modeIcon} aria-hidden="true">
                  {m.icon}
                </span>
                <h2>{t(`study.${m.key}`)}</h2>
                <p>{t(`study.${m.key}Desc`)}</p>
                {prog && <span className={styles.modeProgress}>{prog}</span>}
              </Link>
            </li>
          );
        })}
      </ul>
    </>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import type { CSSProperties, ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import { MagnifyingGlass, Star, ClockCounterClockwise } from '@phosphor-icons/react';
import { TOOLS, TOOL_CATEGORIES, type ToolCategoryId, type ToolMeta } from '@/lib/tools';
import { useToolPrefs } from '@/lib/prefs/toolPrefs';
import { CategoryIcon, TOOL_ICON_WEIGHT } from '@/lib/toolIcons';
import { usePageMeta } from '@/hooks/usePageMeta';
import { itemListLd } from '@/lib/seo/jsonld';
import { Disclaimer } from '@/components/Disclaimer';
import { EmptyState } from '@/components/EmptyState';
import { SectionHeader } from '@/components/SectionHeader';
import { SearchHero } from '@/components/SearchHero';
import type { HeroStat } from '@/components/SearchHero';
import { ViewToggle } from '@/components/hub/ViewToggle';
import { SortSelect } from '@/components/hub/SortSelect';
import { useViewMode } from '@/hooks/useViewMode';
import { ToolCard } from './ToolCard';
import styles from './ToolsIndex.module.css';
import hub from '@/components/hub/hubList.module.css';
import { catToken } from '@/components/categoryTone';

/** Per-category accent — cycles the Falcon hues from the design-token map. */
/** Deterministic category → accent, by the category's order in the master list. */
const catTone = (cat: ToolCategoryId) => catToken(TOOL_CATEGORIES.indexOf(cat));

/** Section heading content: an accent-toned glyph beside the label. */
function TitleWithIcon({ icon, children }: { icon: ReactNode; children: ReactNode }) {
  return (
    <span className={styles.secTitle}>
      {icon}
      <span>{children}</span>
    </span>
  );
}

/** Quick-pick categories surfaced as chips in the hero. */
const POPULAR_CATS: ToolCategoryId[] = [
  'performance',
  'navigation',
  'weight-fuel',
  'atmosphere-weather',
  'regulations',
];

/** Curated flagship tools surfaced in the "Start here" row at the top of the
 *  default view — the most-reached-for calculators. Edit this list to retune. */
const FEATURED: string[] = [
  'crosswind',
  'density-altitude',
  'wind-triangle',
  'fuel-reserves',
  'metar',
  'weight-balance',
];

/** Sort orders; 'category' keeps the grouped view, 'name' goes flat A–Z. */
type SortKey = 'category' | 'name';
const SORTS: SortKey[] = ['category', 'name'];

const VIEW_KEY = 'flygaca:tools-view';

export function ToolsIndex() {
  const { t, i18n } = useTranslation();
  // Expose the live tools as an ItemList so the hub reads as a catalog of its
  // leaf pages for crawlers (the names resolve from i18n by id).
  const toolListLd = useMemo(
    () =>
      itemListLd(
        TOOLS.map((x) => ({
          name: t(`tools.items.${x.id}.name`),
          path: x.route,
        })),
        i18n.language,
      ),
    [t, i18n.language],
  );
  usePageMeta(t('meta.tools'), t('metaDesc.tools'), toolListLd);
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState<ToolCategoryId | 'all'>('all');
  const [sort, setSort] = useState<SortKey>('category');
  const [view, setView] = useViewMode(VIEW_KEY);
  const { favorites, recents } = useToolPrefs();
  const searchRef = useRef<HTMLInputElement>(null);
  const rootRef = useRef<HTMLDivElement>(null);

  const liveCount = TOOLS.length;
  const byId = useMemo(() => new Map(TOOLS.map((tl) => [tl.id, tl])), []);
  const q = query.trim();

  const matches = useMemo(() => {
    const needle = q.toLowerCase();
    if (!needle) return TOOLS;
    return TOOLS.filter((tool) =>
      [
        t(`tools.items.${tool.id}.name`),
        t(`tools.items.${tool.id}.blurb`),
        ...(tool.keywords ?? []),
      ]
        .join(' ')
        .toLowerCase()
        .includes(needle),
    );
  }, [q, t]);

  const filtered = category === 'all' ? matches : matches.filter((x) => x.category === category);
  const grouped = TOOL_CATEGORIES.map((cat) => ({
    cat,
    tools: filtered.filter((x) => x.category === cat),
  })).filter((g) => g.tools.length > 0);
  // Category counts (independent of the active filter) for the chip badges.
  const catCount = useMemo(() => {
    const m = new Map<ToolCategoryId, number>();
    for (const tl of matches) m.set(tl.category, (m.get(tl.category) ?? 0) + 1);
    return m;
  }, [matches]);
  const unfiltered = category === 'all';

  // Group the catalogue only in the default "by category" sort with no active
  // search/filter; otherwise show a single flat grid sorted by the chosen order.
  const showGrouped = sort === 'category' && unfiltered && !q;
  const flat =
    sort === 'name'
      ? [...filtered].sort((a, b) =>
          t(`tools.items.${a.id}.name`).localeCompare(t(`tools.items.${b.id}.name`)),
        )
      : filtered;

  // Featured "Start here" row + pinned/recent rows — grouped (default) view only.
  const featured = FEATURED.map((id) => byId.get(id)).filter((x): x is ToolMeta => Boolean(x));
  const pinned = favorites.map((id) => byId.get(id)).filter((x): x is ToolMeta => Boolean(x));
  const recent = recents
    .map((id) => byId.get(id))
    .filter((x): x is ToolMeta => Boolean(x) && !favorites.includes(x!.id));

  // Animated figures for the hero readout.
  const stats = useMemo<HeroStat[]>(() => {
    const cats = TOOL_CATEGORIES.filter((c) => TOOLS.some((x) => x.category === c)).length;
    return [
      { label: t('tools.stats.tools'), value: liveCount, tone: 'cyan' },
      { label: t('tools.stats.categories'), value: cats, tone: 'green' },
    ];
  }, [t, liveCount]);

  // Quick-pick category chips for the hero; toggle the matching category filter.
  const popularChips = POPULAR_CATS.map((c) => ({
    label: t(`tools.categories.${c}`),
    onClick: () => setCategory((cur) => (cur === c ? 'all' : c)),
    active: category === c,
  }));

  // Press "/" anywhere (outside a field) to focus the search box.
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key !== '/' || e.metaKey || e.ctrlKey) return;
      const el = document.activeElement;
      const typing =
        el instanceof HTMLElement && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA');
      if (typing) return;
      e.preventDefault();
      searchRef.current?.focus();
    }
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);

  // Arrow keys move focus between tool cards in document order.
  function onGridKeyDown(e: React.KeyboardEvent<HTMLDivElement>) {
    const keys = ['ArrowDown', 'ArrowUp', 'ArrowLeft', 'ArrowRight'];
    if (!keys.includes(e.key)) return;
    const items = Array.from(
      rootRef.current?.querySelectorAll<HTMLAnchorElement>('[data-toolcard]') ?? [],
    );
    const at = items.indexOf(document.activeElement as HTMLAnchorElement);
    if (at === -1) return;
    e.preventDefault();
    const fwd = e.key === 'ArrowDown' || e.key === 'ArrowRight';
    const next = fwd ? Math.min(at + 1, items.length - 1) : Math.max(at - 1, 0);
    items[next]?.focus();
  }

  const listClass = `${hub.grid} ${view === 'list' ? hub.list : ''} stagger-grid`;
  const renderGrid = (tools: ToolMeta[]) => (
    <ul className={listClass}>
      {tools.map((tool) => (
        <ToolCard
          key={tool.id}
          tool={tool}
          tone={catTone(tool.category)}
          query={q}
          favorite={favorites.includes(tool.id)}
          view={view}
        />
      ))}
    </ul>
  );

  return (
    <section className={`container ${styles.page}`}>
      <SearchHero
        eyebrow={t('tools.eyebrow')}
        title={t('tools.title')}
        subtitle={t('tools.subtitle')}
        placeholder={t('tools.searchPlaceholder', { count: liveCount })}
        query={query}
        onQueryChange={setQuery}
        stats={stats}
        chipsLabel={t('tools.popular')}
        chips={popularChips}
        inputRef={searchRef}
      />

      <div className={styles.controls}>
        <div className={styles.filters} role="group" aria-label={t('tools.title')}>
          <button
            type="button"
            className={`${styles.filterChip} ${unfiltered ? styles.filterChipActive : ''}`}
            aria-pressed={unfiltered}
            onClick={() => setCategory('all')}
          >
            {t('tools.allCategories')}
          </button>
          {TOOL_CATEGORIES.filter((cat) => (catCount.get(cat) ?? 0) > 0).map((cat) => (
            <button
              key={cat}
              type="button"
              className={`${styles.filterChip} ${category === cat ? styles.filterChipActive : ''}`}
              aria-pressed={category === cat}
              onClick={() => setCategory(cat)}
              style={{ '--cat-color': catTone(cat) } as CSSProperties}
            >
              <CategoryIcon cat={cat} size={16} />
              {t(`tools.categories.${cat}`)}
            </button>
          ))}
        </div>

        <div className={styles.toolbar}>
          <p className={styles.searchMeta} role="status">
            {q ? t('tools.resultCount', { count: matches.length }) : ''}
          </p>
          <div className={styles.toolbarEnd}>
            <SortSelect
              label={t('tools.sortBy')}
              value={sort}
              onChange={(v) => setSort(v as SortKey)}
              options={SORTS.map((s) => ({ value: s, label: t(`tools.sort.${s}`) }))}
            />
            <ViewToggle
              value={view}
              onChange={setView}
              groupLabel={t('tools.view')}
              gridLabel={t('tools.viewGrid')}
              listLabel={t('tools.viewList')}
            />
          </div>
        </div>
      </div>

      <div
        ref={rootRef}
        onKeyDown={onGridKeyDown}
        role="group"
        aria-label={t('tools.title')}
        tabIndex={-1}
      >
        {showGrouped && featured.length > 0 && (
          <section className={styles.category}>
            <SectionHeader title={t('tools.featured')} tone="var(--brand-hover)" />
            <ul className={`${styles.featuredGrid} stagger-grid`}>
              {featured.map((tool) => (
                <ToolCard
                  key={tool.id}
                  tool={tool}
                  tone={catTone(tool.category)}
                  query={q}
                  favorite={favorites.includes(tool.id)}
                  view="grid"
                  featured
                />
              ))}
            </ul>
          </section>
        )}
        {showGrouped && pinned.length > 0 && (
          <section className={styles.category}>
            <SectionHeader
              title={
                <TitleWithIcon icon={<Star size={20} weight="fill" aria-hidden />}>
                  {t('tools.pinned')}
                </TitleWithIcon>
              }
              tone="var(--gold)"
            />
            {renderGrid(pinned)}
          </section>
        )}
        {showGrouped && recent.length > 0 && (
          <section className={styles.category}>
            <SectionHeader
              title={
                <TitleWithIcon
                  icon={<ClockCounterClockwise size={20} weight={TOOL_ICON_WEIGHT} aria-hidden />}
                >
                  {t('tools.recent')}
                </TitleWithIcon>
              }
              tone="var(--cat-2)"
            />
            {renderGrid(recent)}
          </section>
        )}

        {showGrouped && grouped.length > 1 && (
          <nav className={styles.jump} aria-label={t('tools.jumpNav')}>
            {grouped.map(({ cat }) => (
              <a key={cat} href={`#${cat}`} className={styles.jumpChip}>
                <CategoryIcon cat={cat} size={16} />
                {t(`tools.categories.${cat}`)}
              </a>
            ))}
          </nav>
        )}

        {flat.length === 0 ? (
          <EmptyState
            icon={<MagnifyingGlass size={44} weight="regular" aria-hidden />}
            action={{
              label: t('common.clear'),
              onClick: () => {
                setQuery('');
                setCategory('all');
              },
            }}
          >
            {t('tools.empty')}
          </EmptyState>
        ) : showGrouped ? (
          grouped.map(({ cat, tools }) => (
            <section key={cat} id={cat} className={styles.category}>
              <SectionHeader
                title={
                  <TitleWithIcon icon={<CategoryIcon cat={cat} size={20} />}>
                    {t(`tools.categories.${cat}`)}
                  </TitleWithIcon>
                }
                count={t('tools.resultCount', { count: tools.length })}
                tone={catTone(cat)}
              />
              {renderGrid(tools)}
            </section>
          ))
        ) : (
          renderGrid(flat)
        )}
      </div>

      <div className={styles.footnote}>
        <Disclaimer compact />
      </div>
    </section>
  );
}

