import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { CalcShell } from '@/components/CalcShell';
import { NumberField } from '@/components/calc/NumberField';
import { TextField } from '@/components/calc/TextField';
import { ResultStat } from '@/components/calc/ResultStat';
import { FieldGrid, OutputGrid } from '@/components/calc/Grids';
import { useNumericInputs } from '@/hooks/useNumericInputs';
import { useFetchJson } from '@/hooks/useFetchJson';
import type { AirportsIndex } from '@/lib/content';
import { greatCircle } from '@/calc/navigation';
import { formatHours } from '@/calc/fuel';
import table from '@/pages/tools/performance/WindTable.module.css';

export function RoutePlanner() {
  const { t } = useTranslation();
  const { data, loading, error } = useFetchJson<AirportsIndex>('/data/airports.json');
  const { inputs, set, nums } = useNumericInputs({ route: '', gs: '', burn: '' });

  const byIcao = useMemo(() => {
    const m = new Map<string, AirportsIndex['airports'][number]>();
    data?.airports.forEach((a) => m.set(a.icao, a));
    return m;
  }, [data]);

  const codes = inputs.route.trim().toUpperCase().split(/\s+/).filter(Boolean);
  const unknown = codes.filter((c) => /^[A-Z]{4}$/.test(c) && !byIcao.has(c));

  const legs = useMemo(() => {
    const out: { from: string; to: string; distanceNm: number; bearingDeg: number }[] = [];
    for (let i = 0; i < codes.length - 1; i++) {
      const a = byIcao.get(codes[i]);
      const b = byIcao.get(codes[i + 1]);
      if (!a || !b) continue;
      const gc = greatCircle(a.lat, a.lon, b.lat, b.lon);
      if (gc)
        out.push({
          from: codes[i],
          to: codes[i + 1],
          distanceNm: gc.distanceNm,
          bearingDeg: gc.bearingDeg,
        });
    }
    return out;
  }, [codes, byIcao]);

  const total = legs.reduce((s, l) => s + l.distanceNm, 0);
  const gs = nums.gs;
  const burn = nums.burn;
  const timeHr = total > 0 && gs > 0 ? total / gs : null;
  const fuel = timeHr != null && burn > 0 ? burn * timeHr : null;

  return (
    <CalcShell
      title={t('tools.items.route-planner.name')}
      intro={t('tools.items.route-planner.blurb')}
      category={t('tools.categories.navigation')}
      formula={t('routePlanner.formula')}
      onExample={() => {
        set('route', 'OERK OEDF OEJN');
        set('gs', '420');
        set('burn', '1800');
      }}
      related={[
        { to: '/tools/great-circle', label: t('tools.items.great-circle.name') },
        { to: '/tools/aerodromes', label: t('tools.items.aerodromes.name') },
      ]}
    >
      {loading && <p>{t('common.loading')}</p>}
      {error && <p role="alert">{t('common.loadError')}</p>}
      <FieldGrid>
        <TextField
          label={t('routePlanner.route')}
          value={inputs.route}
          onChange={(v) => set('route', v)}
          placeholder="OERK OEDF OEJN"
          hint={t('routePlanner.routeHint')}
        />
        <NumberField
          label={t('routePlanner.gs')}
          value={inputs.gs}
          onChange={(v) => set('gs', v)}
          unit="kt"
          placeholder="420"
        />
        <NumberField
          label={t('routePlanner.burn')}
          value={inputs.burn}
          onChange={(v) => set('burn', v)}
          placeholder="1800"
        />
      </FieldGrid>

      {unknown.length > 0 && (
        <p style={{ color: 'var(--color-error)', fontSize: 'var(--fs-sm)', margin: 0 }}>
          {t('routePlanner.unknown', { codes: unknown.join(', ') })}
        </p>
      )}

      {legs.length > 0 && (
        <>
          <div className={table.tableWrap}>
            <table className={table.table}>
              <thead>
                <tr>
                  <th>{t('routePlanner.legCol')}</th>
                  <th>{t('routePlanner.distCol')}</th>
                  <th>{t('routePlanner.bearingCol')}</th>
                </tr>
              </thead>
              <tbody>
                {legs.map((l, i) => (
                  <tr key={i}>
                    <td>
                      {l.from} → {l.to}
                    </td>
                    <td>{Math.round(l.distanceNm)} NM</td>
                    <td>{Math.round(l.bearingDeg)}°</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <OutputGrid>
            <ResultStat
              label={t('routePlanner.total')}
              value={`${Math.round(total)} NM`}
              tone="headline"
            />
            <ResultStat
              label={t('routePlanner.time')}
              value={timeHr != null ? formatHours(timeHr) : '—'}
            />
            <ResultStat
              label={t('routePlanner.fuel')}
              value={fuel != null ? `${Math.round(fuel)}` : '—'}
            />
          </OutputGrid>
        </>
      )}
    </CalcShell>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { Link, useParams } from 'react-router';
import { useTranslation } from 'react-i18next';
import { CalcShell } from '@/components/CalcShell';
import { useFetchJson } from '@/hooks/useFetchJson';
import { airportLd } from '@/lib/seo/jsonld';
import { regionBadge } from '@/lib/aerodromes';
import { type Airport, type AirportsIndex, type AirspacesIndex } from '@/lib/content';
import { loadShardedData, reassembleAirports } from '@/lib/sharded-loader';
import { AerodromeScope } from '@/components/aerodrome/AerodromeScope';
import { AirportTypeIcon } from '@/components/aerodrome/AirportTypeIcon';
import { RunwayDiagram } from '@/components/aerodrome/RunwayDiagram';
import { PositionMarker } from '@/components/aerodrome/PositionMarker';
import { DaylightStrip } from '@/components/aerodrome/DaylightStrip';
import styles from './Aerodromes.module.css';

export function AerodromeDetail() {
  const { t, i18n } = useTranslation();
  const ar = i18n.language === 'ar';
  const { icao = '' } = useParams();
  const code = icao.toUpperCase();
  const { data, error, loading } = useFetchJson<AirportsIndex>('/data/airports.json');
  const { data: airspaces } = useFetchJson<AirspacesIndex>('/data/airspaces-index.json');

  const inCore = useMemo(() => data?.airports.find((a) => a.icao === code), [data, code]);
  // Long-tail airfields aren't in the eager core file; fetch the lazy tier and
  // look there only when the core misses (so most lookups stay on the core file).
  const [extra, setExtra] = useState<Airport[] | null>(null);
  const [extraLoading, setExtraLoading] = useState(false);
  useEffect(() => {
    if (!data || inCore || extra || extraLoading) return;
    setExtraLoading(true);
    loadShardedData<AirportsIndex>(
      '/data/airports-extra.json',
      '/data/airports-shards',
      reassembleAirports,
    )
      .then((d) => setExtra(d.airports))
      .catch(() => setExtra([]))
      .finally(() => setExtraLoading(false));
  }, [data, inCore, extra, extraLoading]);

  const airport = inCore ?? extra?.find((a) => a.icao === code);

  if (loading || (!inCore && (extraLoading || (data && !extra)))) {
    return (
      <CalcShell title={code} category={t('tools.categories.procedures')}>
        <p>{t('common.loading')}</p>
      </CalcShell>
    );
  }
  if (error || !airport) {
    return (
      // Unknown ICAO (or a failed load) has no content to index — noindex the soft-404.
      <CalcShell title={code} category={t('tools.categories.procedures')} noindex>
        <p role="alert">{error ? t('common.loadError') : t('aerodromesTool.notFound')}</p>
        <Link className={styles.back} to="/tools/aerodromes">
          ← {t('aerodromesTool.backToList')}
        </Link>
      </CalcShell>
    );
  }

  const a = airport;
  const name = ar ? a.name_ar : a.name_en;
  const country = ar ? a.country_ar || a.country_en : a.country_en;
  const city = ar ? a.city_ar || a.city_en : a.city_en;
  const badge = regionBadge(a);

  const adelPrompt = () =>
    ar
      ? `أخبرني عن مطار ${name} (${a.icao}): المدارج والترددات والخدمات.`
      : `Tell me about ${name} (${a.icao}): runways, frequencies and services.`;

  return (
    <CalcShell
      title={`${a.icao} — ${name}`}
      intro={[city, country].filter(Boolean).join(', ')}
      category={t('tools.categories.procedures')}
      formula={t('aerodromesTool.formula')}
      adelPrompt={adelPrompt}
      related={[{ to: '/tools/aerodromes', label: t('aerodromesTool.backToList') }]}
      primaryLd={airportLd({
        name,
        icao: a.icao,
        iata: a.iata,
        path: `/tools/aerodromes/${a.icao}`,
        lang: i18n.language,
        lat: a.lat,
        lon: a.lon,
        elevationFt: a.elev_ft,
        country,
      })}
    >
      <div className={styles.detailHead}>
        <AirportTypeIcon type={a.type} className={styles.detailTypeIcon} />
        <span className={styles.detailIcao}>{a.icao}</span>
        {a.iata && <span className={styles.iata}>{a.iata}</span>}
        <span className={`${styles.badge} ${styles[`badge_${badge}`]}`}>
          {t(`aerodromesTool.regions.${badge}`)}
        </span>
      </div>

      <div className={styles.overview}>
        <dl className={styles.facts}>
          {country && (
            <div className={styles.fact}>
              <dt>{t('aerodromesTool.country')}</dt>
              <dd>{country}</dd>
            </div>
          )}
          <div className={styles.fact}>
            <dt>{t('aerodromesTool.elevation')}</dt>
            <dd>{a.elev_ft.toLocaleString()} ft</dd>
          </div>
          <div className={styles.fact}>
            <dt>{t('aerodromesTool.coordinates')}</dt>
            <dd className={styles.coords}>
              {a.lat.toFixed(4)}, {a.lon.toFixed(4)}
            </dd>
          </div>
          {a.mag && (
            <div className={styles.fact}>
              <dt>{t('aerodromesTool.magVar')}</dt>
              <dd>{a.mag}</dd>
            </div>
          )}
        </dl>
        <PositionMarker lat={a.lat} lon={a.lon} />
      </div>

      <section className={styles.detailSection}>
        <h2 className={styles.detailH2}>{t('aerodromesTool.daylight')}</h2>
        <DaylightStrip lat={a.lat} lon={a.lon} />
      </section>

      {a.rwys.length > 0 && (
        <section className={styles.detailSection}>
          <h2 className={styles.detailH2}>{t('aerodromesTool.runways')}</h2>
          <div className={styles.rwyLayout}>
            <RunwayDiagram rwys={a.rwys} />
            <ul className={styles.rwyList}>
              {a.rwys.map((r, i) => (
                <li key={i} className={styles.rwyRow}>
                  <span className={styles.rwyId}>{r.id}</span>
                  {r.len && <span className={styles.rwyMeta}>{r.len.toLocaleString()} ft</span>}
                  {r.surf && <span className={styles.rwyMeta}>{r.surf}</span>}
                </li>
              ))}
            </ul>
          </div>
        </section>
      )}

      {a.freqs.length > 0 && (
        <section className={styles.detailSection}>
          <h2 className={styles.detailH2}>{t('aerodromesTool.freqs')}</h2>
          <div className={styles.pills}>
            {a.freqs.map((f, i) => (
              <span key={i} className={styles.freq}>
                {f.l} {f.v}
              </span>
            ))}
          </div>
        </section>
      )}

      {a.services && a.services.length > 0 && (
        <section className={styles.detailSection}>
          <h2 className={styles.detailH2}>{t('aerodromesTool.services')}</h2>
          <dl className={styles.facts}>
            {a.services.map((s, i) => (
              <div key={i} className={styles.fact}>
                <dt>{s.l}</dt>
                <dd>{s.v}</dd>
              </div>
            ))}
          </dl>
        </section>
      )}

      <AerodromeScope
        center={{ lat: a.lat, lon: a.lon }}
        icao={a.icao}
        zones={airspaces?.airspaces ?? []}
      />

      <a
        className={styles.map}
        href={`https://www.google.com/maps?q=${a.lat},${a.lon}`}
        target="_blank"
        rel="noopener noreferrer"
      >
        {t('aerodromesTool.viewMap')}
      </a>
    </CalcShell>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router';
import { useTranslation } from 'react-i18next';
import { CalcShell } from '@/components/CalcShell';
import { TextField } from '@/components/calc/TextField';
import { useFetchJson } from '@/hooks/useFetchJson';
import { useDebouncedValue } from '@/hooks/useDebouncedValue';
import { useUrlState } from '@/hooks/useUrlState';
import { type Airport, type AirportsIndex } from '@/lib/content';
import { loadShardedData, reassembleAirports } from '@/lib/sharded-loader';
import {
  REGION_FILTERS,
  inRegion,
  regionBadge,
  compareAirports,
  type RegionFilter,
} from '@/lib/aerodromes';
import { AerodromesHero } from '@/components/aerodrome/AerodromesHero';
import { AirportTypeIcon } from '@/components/aerodrome/AirportTypeIcon';
import styles from './Aerodromes.module.css';

const PAGE = 60;

export function Aerodromes() {
  const { t, i18n } = useTranslation();
  const ar = i18n.language === 'ar';
  const { data, error, loading } = useFetchJson<AirportsIndex>('/data/airports.json');
  // Search and region live in the URL so a filtered view is shareable; an empty
  // region means "all" (kept out of the query string to keep links clean).
  const [urlState, setUrl] = useUrlState({ q: '', region: '' });
  const region = (urlState.region || 'all') as RegionFilter;
  const [visible, setVisible] = useState(PAGE);
  const query = useDebouncedValue(urlState.q.trim(), 200);

  // The long tail (small strips, heliports — ~66k airfields) ships in a separate
  // file fetched lazily the first time a search or a region filter is active, so
  // the default "All" view only pays for the ~6k rich core. Mirrors the Library's
  // lazy search-index pattern.
  const needExtra = region !== 'all' || query.length > 0;
  const [extra, setExtra] = useState<Airport[] | null>(null);
  const [extraLoading, setExtraLoading] = useState(false);
  useEffect(() => {
    if (!needExtra || extra || extraLoading) return;
    setExtraLoading(true);
    loadShardedData<AirportsIndex>(
      '/data/airports-extra.json',
      '/data/airports-shards',
      reassembleAirports,
    )
      .then((d) => setExtra(d.airports))
      .catch(() => setExtra([]))
      .finally(() => setExtraLoading(false));
  }, [needExtra, extra, extraLoading]);

  const pool = useMemo(() => {
    const base = data?.airports ?? [];
    return extra ? base.concat(extra) : base;
  }, [data, extra]);

  const matches = useMemo(() => {
    if (!data) return [];
    const needle = query.toLowerCase();
    return pool
      .filter((a) => inRegion(a, region))
      .filter(
        (a) =>
          !needle ||
          a.icao.toLowerCase().includes(needle) ||
          a.iata.toLowerCase().includes(needle) ||
          a.name_en.toLowerCase().includes(needle) ||
          a.name_ar.includes(query) ||
          a.city_en.toLowerCase().includes(needle) ||
          (a.country_en?.toLowerCase().includes(needle) ?? false),
      )
      .sort(compareAirports);
  }, [data, pool, query, region]);

  const list = useMemo(() => matches.slice(0, visible), [matches, visible]);

  function pickRegion(next: RegionFilter) {
    setUrl('region', next === 'all' ? '' : next);
    setVisible(PAGE);
  }
  function onSearch(next: string) {
    setUrl('q', next);
    setVisible(PAGE);
  }

  const adelPrompt = () => {
    const term = urlState.q.trim();
    if (!term) return null;
    return ar
      ? `ما هي مدارج وترددات وخدمات مطار "${term}"؟`
      : `What are the runways, frequencies and services for the aerodrome "${term}"?`;
  };

  return (
    <CalcShell
      title={t('tools.items.aerodromes.name')}
      intro={t('tools.items.aerodromes.blurb')}
      category={t('tools.categories.procedures')}
      formula={t('aerodromesTool.formula')}
      adelPrompt={adelPrompt}
    >
      <AerodromesHero />
      <div className={styles.regions} role="group" aria-label={t('aerodromesTool.regionLabel')}>
        {REGION_FILTERS.map((r) => (
          <button
            key={r}
            type="button"
            className={`${styles.region} ${region === r ? styles.regionActive : ''}`}
            aria-pressed={region === r}
            onClick={() => pickRegion(r)}
          >
            {t(`aerodromesTool.regions.${r}`)}
          </button>
        ))}
      </div>

      <TextField
        label={t('aerodromesTool.search')}
        value={urlState.q}
        onChange={onSearch}
        placeholder="OERK"
      />

      {loading && <p>{t('common.loading')}</p>}
      {error && <p role="alert">{t('common.loadError')}</p>}
      {data && (
        <>
          <p className={styles.count}>
            {extraLoading
              ? t('aerodromesTool.searchingWorldwide')
              : region === 'all' && !query
                ? t('aerodromesTool.count', { n: matches.length })
                : matches.length > list.length
                  ? t('aerodromesTool.showing', { n: list.length, total: matches.length })
                  : t('aerodromesTool.matched', { n: matches.length })}
          </p>
          {list.length === 0 ? (
            <p className={styles.count}>{t('aerodromesTool.empty')}</p>
          ) : (
            <>
              <ul className={`${styles.list} stagger-grid`}>
                {list.map((a) => {
                  const badge = regionBadge(a);
                  return (
                    <li key={a.icao} className={styles.card}>
                      <Link
                        to={`/tools/aerodromes/${encodeURIComponent(a.icao)}`}
                        className={styles.cardLink}
                      >
                        <span className={styles.head}>
                          <AirportTypeIcon type={a.type} className={styles.cardTypeIcon} />
                          <span className={styles.icao}>{a.icao}</span>
                          {a.iata && <span className={styles.iata}>{a.iata}</span>}
                          <span
                            className={`${styles.badge} ${styles[`badge_${badge}`]}`}
                            title={t(`aerodromesTool.regions.${badge}`)}
                          >
                            {t(`aerodromesTool.regions.${badge}`)}
                          </span>
                        </span>
                        <span className={styles.name}>{ar ? a.name_ar : a.name_en}</span>
                        <span className={styles.meta}>
                          {a.country_en && (
                            <span>{ar ? a.country_ar || a.country_en : a.country_en}</span>
                          )}
                          <span>
                            {t('aerodromesTool.elevation')}: {a.elev_ft.toLocaleString()} ft
                          </span>
                          <span className={styles.coords}>
                            {a.lat.toFixed(3)}, {a.lon.toFixed(3)}
                          </span>
                        </span>
                        {a.rwys.length > 0 && (
                          <span className={styles.rowSection}>
                            <span className={styles.rowLabel}>{t('aerodromesTool.runways')}</span>
                            <span className={styles.pills}>
                              {a.rwys.map((r, i) => (
                                <span
                                  key={i}
                                  className={styles.rwy}
                                  title={
                                    r.len
                                      ? `${r.len.toLocaleString()} ft${r.surf ? ` · ${r.surf}` : ''}`
                                      : r.surf || undefined
                                  }
                                >
                                  {r.id}
                                </span>
                              ))}
                            </span>
                          </span>
                        )}
                        {a.freqs.length > 0 && (
                          <span className={styles.rowSection}>
                            <span className={styles.rowLabel}>{t('aerodromesTool.freqs')}</span>
                            <span className={styles.pills}>
                              {a.freqs.map((f, i) => (
                                <span key={i} className={styles.freq}>
                                  {f.l} {f.v}
                                </span>
                              ))}
                            </span>
                          </span>
                        )}
                      </Link>
                    </li>
                  );
                })}
              </ul>
              {matches.length > list.length && (
                <button
                  type="button"
                  className={styles.loadMore}
                  onClick={() => setVisible((v) => v + PAGE)}
                >
                  {t('aerodromesTool.loadMore')}
                </button>
              )}
            </>
          )}
        </>
      )}
    </CalcShell>
  );
}
